jQuery(document).ready(function(a){wf_fed_ex_load_packing_method_options();jQuery(".packing_method").change(function(){wf_fed_ex_load_packing_method_options()});a(".multiselect.chosen_select").select2();a("#woocommerce_wf_shipping_ups_availability").change(function(){var b=a(this).parents("tr").next("tr");if(a(this).val()=="all"){b.hide()}else{b.show()}}).change()});function wf_fed_ex_load_packing_method_options(){pack_method=jQuery(".packing_method").val();jQuery("#packing_options").hide();jQuery(".weight_based_option").closest("tr").hide();switch(pack_method){case"per_item":default:break;case"box_packing":jQuery("#packing_options").show();break;case"weight_based":jQuery(".weight_based_option").closest("tr").show();break}};